const GC_GOLD_CHANCE = 1 / 3;

const GC_COLORS = [
  { name: "招財黃", css: "--o:#9A7432;--b:#F3D88E;--l:#9A7432;--e:#F2B8B5" },
  { name: "戀愛粉", css: "--o:#A8706B;--b:#F2C9C4;--l:#A8706B;--e:#E8A09A" },
  { name: "健康綠", css: "--o:#66724A;--b:#BEC79F;--l:#66724A;--e:#F2B8B5" },
  { name: "炭錢黑", css: "--o:#2B2724;--b:#3D3935;--l:#EFE6D6;--e:#F2B8B5" },
  { name: "純淨白", css: "--o:#8C7B66;--b:#FAF6EE;--l:#8C7B66;--e:#F2B8B5" },
  { name: "清水灰", css: "--o:#5E5E5A;--b:#BDBDB8;--l:#5E5E5A;--e:#F2B8B5" },
];

const GC_TIPS = [
  "先點上面的<b>平台按鈕</b>,再按「開啟後台」就能進平台。",
  "<b>蝦皮、Pinkoi、官網</b>要開發票,其他平台不用。",
  "LINE禮物:丟訂單總表 → 下載黑貓出貨表 → 上傳包貨平台與試算表。",
  "印單前先看預覽,有 ⚠ 或 ❗ 的先問人再印。",
  "紙張預設是黑貓熱感應,按印單鈕旁邊的<b>小箭頭</b>可以換 4×6。",
  "客人有狀況記到「問題訂單」,退回來的包裹記到「包裹退貨」。",
];

const GC_REMIND_HOURS = [9, 11, 13, 15, 17];       // 定點提醒的時間(整點)
const GC_SHOPEE_CHAT = "https://seller.shopee.tw/webchat/conversations";
const GC_KEY = "guideCatLastAck";

const GC_CALL_SKIP_KEY = "guideCatCallSkip";   // 按「今天先不打」的日期
const GC_CALL_NOTIFIED_KEY = "guideCatCallNotified";   // 今天的打電話通知跳過了沒(一天只跳一次)
const GC_PLATFORM_CHECK_KEY = "guideCatPlatformCheck";   // 今天已經「已檢查」的平台 id({date, ids:[...]}),隔天自動重置
const GC_PLAT_NOTIFIED_KEY = "guideCatPlatNotified";   // 今天的「檢查新訂單」通知跳過了沒(一天只跳一次)
let gcCalls = 0;                                  // 今天還要打幾筆
let gcCallItems = [];                             // 今天要打電話的那幾筆(拿訂單編號出來顯示用)
let gcTip = -1;
let gcReminding = false;
const gcTitle = document.title;

// 今天已經到了的最後一個提醒時段(Date),還沒到 9:00 就是 null
function gcCurrentSlot(now = new Date()) {
  let slot = null;
  for (const h of GC_REMIND_HOURS) {
    const t = new Date(now); t.setHours(h, 0, 0, 0);
    if (t <= now) slot = t;
  }
  return slot;
}

function gcLastAck() {
  let t = 0;
  try { t = Number(localStorage.getItem(GC_KEY)) || 0; } catch (e) {}
  if (!t) { t = Date.now(); gcSetAck(t); }   // 第一次打開:從現在開始算
  return t;
}
function gcSetAck(t) { try { localStorage.setItem(GC_KEY, String(t)); } catch (e) {} }

// ---- 桌面通知(Windows 右下角跳出來,切到別的網站也看得到) ----
// 限制:要按過「允許」、出貨幫手的分頁要開著(可以在背景或縮小)、只有 https 網址能用(本機 file:// 不行)
function gcNotifySupported() {
  return "Notification" in window && window.isSecureContext;
}

// 上班時間:週一到週五 9:00~18:00(使用者 2026-10-16:下班後千萬不要通知)。
// 下班時間蝦皮、打電話兩種提醒都不出現 —— 桌面通知、泡泡變色、分頁標題都沒有。
// 測試網址(#test-…)不受限制,隨時都能測。
let gcTestMode = false;
function gcWorkHours(d = new Date()) {
  const day = d.getDay(), h = d.getHours();
  return day >= 1 && day <= 5 && h >= 9 && h < 18;
}
function gcCanRemind() { return gcTestMode || gcWorkHours(); }

// 設定裡的開關(只存在這台電腦)。瀏覽器的「允許」沒辦法從網頁收回,所以用自己的開關擋
const GC_NOTIFY_OFF_KEY = "guideCatNotifyOff";
function gcNotifyOn() {
  try { return localStorage.getItem(GC_NOTIFY_OFF_KEY) !== "1"; } catch (e) { return true; }
}

function gcSetNotifyOn(on) {
  try { localStorage.setItem(GC_NOTIFY_OFF_KEY, on ? "0" : "1"); } catch (e) {}
  // 打開時如果還沒允許過,順便問瀏覽器
  if (on && gcNotifySupported() && Notification.permission === "default") gcAskNotify();
  gcSyncNotifyToggle();
  gcRenderNotifyBtn();
}

function gcSyncNotifyToggle() {
  const cb = document.getElementById("notifyToggle");
  if (!cb) return;
  const on = gcNotifyOn();
  cb.checked = on;
  document.getElementById("notifyToggleText").textContent = on ? "開啟" : "關閉";
  const hint = document.getElementById("notifyToggleHint");
  let msg = "";
  if (!gcNotifySupported()) msg = "這裡不能用桌面通知(要用正式網址開)。";
  else if (on && Notification.permission === "denied") msg = "瀏覽器把通知封鎖了:點網址列左邊的鎖頭 → 通知 → 允許。";
  else if (on && Notification.permission === "default") msg = "還沒允許:打開開關時瀏覽器會問,按「允許」。";
  hint.textContent = msg;
  hint.style.display = msg ? "" : "none";
}

function gcNotify(title, body, tag, force) {
  if (!gcNotifySupported() || Notification.permission !== "granted") return;
  if (!gcNotifyOn()) return;
  if (!force && !gcCanRemind()) return;
  try {
    const n = new Notification(title, {
      body, tag,
      icon: "icon.png",
      requireInteraction: true,   // 不會自己消失,要人按掉
    });
    n.onclick = () => { window.focus(); n.close(); };
  } catch (e) {
    console.warn("桌面通知失敗:", e);
  }
}

// 貓下面那一行:還沒允許就顯示「開啟桌面通知」按鈕;被封鎖就說去哪裡開
function gcRenderNotifyBtn() {
  const box = document.getElementById("gcNotify");
  if (!box) return;
  if (!gcNotifySupported()) { box.innerHTML = ""; return; }
  const p = Notification.permission;
  if (p === "granted" || !gcNotifyOn()) box.innerHTML = "";   // 已允許、或在設定裡關掉了,就不顯示這顆
  else if (p === "denied") box.innerHTML = `<span class="gc-notify-off" title="點網址列左邊的鎖頭 → 通知 → 允許">桌面通知被封鎖了<br>(網址列左邊鎖頭可以改)</span>`;
  else box.innerHTML = `<button type="button" class="gc-notify-btn" onclick="gcAskNotify()">開啟桌面通知</button>`;
}

function gcAskNotify() {
  if (!gcNotifySupported()) return;
  Notification.requestPermission().then(p => {
    gcRenderNotifyBtn();
    gcSyncNotifyToggle();
    if (p === "granted") gcNotify("出貨小助手", "桌面通知開好了!上班時間(週一到週五 9:00~18:00)時間到會在這裡提醒你。", "gc-hello", true);
  });
}

// 測試用:網址後面加 #test-notify,馬上跳一則測試通知(還沒允許的話先問)
function gcTestNotify() {
  if (!gcNotifySupported()) { gcSay("這裡不能用桌面通知<br>(要用正式網址開)"); return; }
  if (Notification.permission === "granted") gcNotify("出貨小助手(測試)", "看到這個就代表桌面通知正常!", "gc-test", true);
  else gcAskNotify();
}

// 畫一張普通的泡泡卡(測試訊息在用;平常的內容走 gcRender)
function gcSay(html) {
  const box = document.getElementById("gcCards");
  if (box) box.innerHTML = `<div class="gc-bubble">${html}</div>`;
}

function gcTodayKey() {
  const t = new Date();
  return t.getFullYear() + "-" + (t.getMonth() + 1) + "-" + t.getDate();
}
function gcCallSkippedToday() {
  try { return localStorage.getItem(GC_CALL_SKIP_KEY) === gcTodayKey(); } catch (e) { return false; }
}

// 平台檢查清單:每天要把 PLATFORMS 裡每個平台都點過「已檢查」,隔天自動重新全部變成未檢查
function gcCheckedPlatformIds() {
  try {
    const raw = JSON.parse(localStorage.getItem(GC_PLATFORM_CHECK_KEY) || "null");
    if (raw && raw.date === gcTodayKey() && Array.isArray(raw.ids)) return new Set(raw.ids);
  } catch (e) {}
  return new Set();
}
function gcSetPlatformChecked(id) {
  const ids = gcCheckedPlatformIds();
  ids.add(id);
  try { localStorage.setItem(GC_PLATFORM_CHECK_KEY, JSON.stringify({ date: gcTodayKey(), ids: [...ids] })); } catch (e) {}
}
function gcUncheckedPlatforms() {
  const checked = gcCheckedPlatformIds();
  return PLATFORMS.filter(p => !checked.has(p.id));
}
function gcTogglePlatformChecked(id) {
  gcSetPlatformChecked(id);
  gcRender();   // 不用 gcIdle:勾平台不該把還亮著的蝦皮提醒一起收掉
}

// ---- 泡泡:三種提醒各自一張卡,同時出現就由上往下排 ----
// 2026-10-20 之前是優先序(蝦皮 > 打電話 > 檢查新訂單)只顯示最急的那一張,
// 另外兩張整個被蓋掉 —— 同事就看不到今天還有電話沒打、還有平台沒檢查。
// 現在幾個成立就畫幾張,顏色掛在卡片自己身上,最下面那張才有指著貓的尖角。
function gcWantCall() { return gcCalls > 0 && !gcCallSkippedToday() && gcCanRemind(); }
function gcWantPlat() { return gcCanRemind() && gcUncheckedPlatforms().length > 0; }

function gcShopeeCard() {
  const slot = gcCurrentSlot();
  const at = slot ? slot.getHours() + ":00" : "";
  return `<div class="gc-bubble is-shopee">
      <b class="gc-remind-title">該看蝦皮訊息囉!</b>${at ? at + " " : ""}看訊息時間到了
      <span class="gc-btns">
        <a class="gc-btn" href="${GC_SHOPEE_CHAT}" target="_blank" rel="noopener noreferrer" onclick="gcAck()">開啟聊聊</a>
        <button type="button" class="gc-btn ghost" onclick="gcAck()">我看過了</button>
      </span>
    </div>`;
}

// 訂單編號、託運單號都沒有的話(理論上不會發生,退貨紀錄擇一必填)用 ? 頂著,不要讓整行空白看起來像壞掉。
// 使用者 2026-10-21:前面加「#」比較好認;原始編號本來就很長(例如 202608130100002574),
// 卡片那邊用 gc-call-ids 這個 class 讓它能在數字中間自己換行,不要撐爆這張窄窄的卡片。
function gcCallOrderIdList() {
  return gcCallItems.map(r => {
    const id = String(r.orderId || r.trackingNo || "?").trim();
    return id.startsWith("#") ? id : "#" + id;
  });
}
// 卡片用(HTML,要跳脫);桌面通知是純文字,直接用 gcCallOrderIdList() 的陣列就好,不要跳脫過的版本
function gcCallOrderIds() {
  return gcCallOrderIdList().map(escapeHtml).join("、");
}

function gcCallCard() {
  const ids = gcCallOrderIds();
  return `<div class="gc-bubble is-call">
      <b class="gc-remind-title">要打電話囉!</b>今天還有 ${gcCalls} 筆退貨要聯絡${ids ? `:<span class="gc-call-ids">${ids}</span>` : ""}
      <span class="gc-btns">
        <button type="button" class="gc-btn" onclick="gcGoReturns()">去包裹退貨</button>
        <button type="button" class="gc-btn ghost" onclick="gcSkipCalls()">今天先不打</button>
      </span>
    </div>`;
}

function gcPlatCard() {
  const unchecked = gcUncheckedPlatforms();
  return `<div class="gc-bubble is-plat">
      <b class="gc-remind-title">檢查新訂單</b>還沒檢查的平台:
      <span class="gc-plat-list">${unchecked.map(p =>
        `<button type="button" class="gc-plat-chip" onclick="gcTogglePlatformChecked('${p.id}')">☐ ${escapeHtml(p.name)}</button>`).join("")}</span>
    </div>`;
}

function gcTipCard() {
  if (gcTip < 0) return `<div class="gc-bubble">我是出貨小助手<br>點我看小提醒</div>`;
  return `<div class="gc-bubble"><span class="gc-n">${gcTip + 1}/${GC_TIPS.length}</span>${GC_TIPS[gcTip]}</div>`;
}

// 現在畫面上「應該」長怎樣。跟上次畫的一樣就不重畫,不然每分鐘一次的檢查會把
// 閃爍動畫重頭跑、也會把同事正在看的小提醒洗掉
function gcSig() {
  return [
    gcReminding,
    gcWantCall() ? gcCalls : 0,
    gcWantPlat() ? gcUncheckedPlatforms().map(p => p.id).join(",") : "",
    gcTip,
  ].join("|");
}
let gcLastSig = null;

function gcRender() {
  const el = document.getElementById("guideCat");
  const box = document.getElementById("gcCards");
  if (!el || !box) return;
  const call = gcWantCall(), plat = gcWantPlat();

  const cards = [];
  if (gcReminding) cards.push(gcShopeeCard());
  if (call) cards.push(gcCallCard());
  if (plat) cards.push(gcPlatCard());
  // 沒有任何提醒就顯示平常那句;有提醒時只有點過貓(看小提醒)才多掛一張在最下面
  if (cards.length === 0 || gcTip >= 0) cards.push(gcTipCard());
  box.innerHTML = cards.join("");

  // 貓本身的動畫速度還是看狀態(class 留著,gcCheck 也沒在看了,但樣式有用到)
  el.classList.toggle("remind", gcReminding);
  el.classList.toggle("call", call);
  el.classList.toggle("platcheck", plat);
  document.title = gcReminding ? "【看蝦皮訊息】" + gcTitle : gcTitle;   // 分頁在背景也看得到
  gcLastSig = gcSig();
}

// 收掉蝦皮提醒(按過「我看過了」或下班)後重畫
function gcIdle() {
  gcReminding = false;
  gcRender();
}

// returns.js 每次讀到退貨資料都會叫這支
function gcUpdateReturnCalls() {
  gcCallItems = (typeof returnsToCallToday === "function") ? returnsToCallToday() : [];
  gcCalls = gcCallItems.length;
  gcRender();
  gcNotifyCalls();
}

// 打電話的桌面通知一天只跳一次(每小時重讀退貨,不能每小時都跳)
function gcNotifyCalls() {
  if (gcCalls <= 0 || gcCallSkippedToday() || !gcCanRemind()) return;
  let done = false;
  try { done = localStorage.getItem(GC_CALL_NOTIFIED_KEY) === gcTodayKey(); } catch (e) {}
  if (done || !gcNotifySupported() || Notification.permission !== "granted") return;
  const ids = gcCallOrderIdList().join("、");
  gcNotify("要打電話囉!", `今天還有 ${gcCalls} 筆退貨要聯絡(LINE禮物)${ids ? ":" + ids : ""}`, "gc-call");
  try { localStorage.setItem(GC_CALL_NOTIFIED_KEY, gcTodayKey()); } catch (e) {}
}

// 「檢查新訂單」的桌面通知:一天只跳一次(這三種提醒以前只有這個沒有桌面通知)
function gcNotifyPlatCheck() {
  if (!gcWantPlat()) return;
  let done = false;
  try { done = localStorage.getItem(GC_PLAT_NOTIFIED_KEY) === gcTodayKey(); } catch (e) {}
  if (done || !gcNotifySupported() || Notification.permission !== "granted") return;
  const names = gcUncheckedPlatforms().map(p => p.name).join("、");
  gcNotify("檢查新訂單", `今天還沒檢查:${names}`, "gc-platcheck");
  try { localStorage.setItem(GC_PLAT_NOTIFIED_KEY, gcTodayKey()); } catch (e) {}
}

function gcGoReturns() {
  switchTab("returns");
  const radio = document.querySelector('input[name="returnPlatform"][value="line禮物"]');
  if (radio && !radio.checked) { radio.checked = true; onReturnPlatformChange(); }
  const open = document.querySelector('input[name="returnFilter"][value="open"]');
  if (open && !open.checked) { open.checked = true; onReturnFilterChange(); }
  document.getElementById("returnList")?.scrollIntoView({ behavior: "smooth", block: "start" });
}

function gcSkipCalls() {
  try { localStorage.setItem(GC_CALL_SKIP_KEY, gcTodayKey()); } catch (e) {}
  gcRender();   // 同上:只收掉打電話那張
}

// 點貓:小提醒多掛一張卡在最下面,上面的提醒卡照樣留著(以前會被整個蓋掉)
function gcNextTip() {
  gcTip = (gcTip + 1) % GC_TIPS.length;
  gcRender();
}

// 時間到:蝦皮那張卡變橘色、一閃一閃,不按按鈕不會變回來(使用者 2026-10-16:不要正中間跳窗,變色就好)
function gcRemind() {
  if (gcReminding || !gcCanRemind()) return;
  gcReminding = true;
  gcRender();
  const slot = gcCurrentSlot();
  const at = slot ? slot.getHours() + ":00" : "";
  // 同一次提醒只跳一則(gcReminding 擋住重複),按了「我看過了」就等下一個時段
  gcNotify("該看蝦皮訊息囉!", `${at ? at + " " : ""}看訊息時間到了,去蝦皮聊聊看看有沒有客人在問。`, "gc-shopee");
}

function gcAck() {
  gcSetAck(Date.now());
  gcIdle();
}

// 測試用:網址後面加 #test-remind 打開,會馬上跳提醒(不用等到整點)
function gcTestRemind() {
  gcTestMode = true;
  gcReminding = false;
  gcRemind();
}

// 測試用:網址後面加 #test-call,假裝今天有 3 筆退貨要打電話
function gcTestCall() {
  gcTestMode = true;
  try { localStorage.removeItem(GC_CALL_SKIP_KEY); } catch (e) {}
  gcCallItems = [{ orderId: "#0002434" }, { orderId: "#0002441" }, { orderId: "#0002458" }];
  gcCalls = gcCallItems.length;
  gcReminding = false;
  gcIdle();
}

// 測試用:網址後面加 #test-platcheck,假裝今天所有平台都還沒檢查
function gcTestPlatCheck() {
  gcTestMode = true;
  try { localStorage.removeItem(GC_PLATFORM_CHECK_KEY); } catch (e) {}
  gcCallItems = [];
  gcCalls = 0;
  gcReminding = false;
  gcIdle();
}

// 測試用:網址後面加 #test-all,三種提醒一起出現(看並排的樣子)
function gcTestAll() {
  gcTestMode = true;
  try {
    localStorage.removeItem(GC_CALL_SKIP_KEY);
    localStorage.removeItem(GC_PLATFORM_CHECK_KEY);
  } catch (e) {}
  gcCallItems = [{ orderId: "#0002434" }, { orderId: "#0002441" }, { orderId: "#0002458" }];
  gcCalls = gcCallItems.length;
  gcReminding = false;
  gcRemind();
}

// 每分鐘跑一次。下班時間:還亮著的提醒安靜收掉(不算「看過了」,所以隔天 9:00 一上班就會提醒);
// 上班時間:最近一個提醒時段之後還沒人按過「看過了」就提醒;打電話的泡泡也在 9:00 一到就出現
function gcCheck() {
  if (!gcCanRemind()) {
    if (gcReminding || gcSig() !== gcLastSig) gcIdle();   // 下班:提醒安靜收掉
    return;
  }
  const slot = gcCurrentSlot();
  if (slot && gcLastAck() < slot.getTime()) gcRemind();
  else if (gcSig() !== gcLastSig) gcRender();   // 該出現/該消失的才重畫
  gcNotifyCalls();
  gcNotifyPlatCheck();
}

// ---- 拖曳:貓咪小助手可以拖到畫面任何地方,位置記在 localStorage,重新整理、換頁都還在原位 ----
// 使用者 2026-10-20 要求。拖的手把是貓本身那顆按鈕(本來點一下是「看小提醒」),
// 用 Pointer Events 分辨「點一下」跟「拖曳」:移動超過 4px 才算拖曳,拖完那一下
// 放開滑鼠要擋掉接下來那個 click,不然放開的瞬間會順便觸發一次「看小提醒」。
const GC_POS_KEY = "guideCatPos";
function gcSavePos(left, top) {
  try { localStorage.setItem(GC_POS_KEY, JSON.stringify({ left, top })); } catch (e) {}
}
function gcLoadPos() {
  try { return JSON.parse(localStorage.getItem(GC_POS_KEY) || "null"); } catch (e) { return null; }
}
// 套用位置,順便夾在視窗範圍內(拖到螢幕外、或換了更小的視窗都不會不見)
function gcApplyPos(el, left, top) {
  const w = el.offsetWidth || 118, h = el.offsetHeight || 200;
  left = Math.max(4, Math.min(left, window.innerWidth - w - 4));
  top = Math.max(4, Math.min(top, window.innerHeight - h - 4));
  el.style.left = left + "px";
  el.style.top = top + "px";
  el.style.right = "auto";
  el.style.bottom = "auto";
  el.style.transform = "none";
  return { left, top };
}
function gcSetupDrag(el) {
  const handle = el.querySelector(".gc-cat-btn");
  let startX = 0, startY = 0, startLeft = 0, startTop = 0, moved = false;
  const onMove = (e) => {
    const dx = e.clientX - startX, dy = e.clientY - startY;
    if (!moved && Math.hypot(dx, dy) < 4) return;
    if (!moved) { moved = true; el.classList.add("dragging"); }
    const pos = gcApplyPos(el, startLeft + dx, startTop + dy);
    gcSavePos(pos.left, pos.top);
  };
  const onUp = () => {
    document.removeEventListener("pointermove", onMove);
    document.removeEventListener("pointerup", onUp);
    if (moved) {
      el.classList.remove("dragging");
      // 拖完放開那一下不要順便觸發貓的 onclick(看小提醒)
      handle.addEventListener("click", (ev) => { ev.stopPropagation(); ev.preventDefault(); }, { capture: true, once: true });
    }
  };
  handle.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;   // 只認滑鼠左鍵(觸控 button 是 0)
    const rect = el.getBoundingClientRect();
    startX = e.clientX; startY = e.clientY;
    startLeft = rect.left; startTop = rect.top;
    moved = false;
    document.addEventListener("pointermove", onMove);
    document.addEventListener("pointerup", onUp);
  });
}

function setupGuideCat() {
  const c = GC_COLORS[Math.floor(Math.random() * GC_COLORS.length)];
  const gold = Math.random() < GC_GOLD_CHANCE;
  const kind = gold ? "金運" : "招福";
  const el = document.createElement("aside");
  el.id = "guideCat";
  el.className = "guide-cat";
  el.setAttribute("aria-live", "polite");
  el.innerHTML = `
    <svg width="0" height="0" style="position:absolute" aria-hidden="true">${GC_SYMBOL}${GC_SYMBOL_GOLD}</svg>
    <div id="gcCards" class="gc-cards"></div>
    <button type="button" class="gc-cat-btn" title="${c.name}${kind}貓:點我看小提醒" onclick="gcNextTip()">
      <svg class="gc-cat" viewBox="0 0 418 462" style="${c.css}" aria-hidden="true"><use href="#${gold ? "gc-cat-gold" : "gc-cat-fu"}"/></svg>
    </button>
    <div id="gcNotify" class="gc-notify"></div>`;
  document.body.appendChild(el);
  const savedPos = gcLoadPos();
  if (savedPos) gcApplyPos(el, savedPos.left, savedPos.top);
  gcSetupDrag(el);
  window.addEventListener("resize", () => {
    const p = gcLoadPos();
    if (!p) return;
    const clamped = gcApplyPos(el, p.left, p.top);
    gcSavePos(clamped.left, clamped.top);
  });
  gcRender();
  gcRenderNotifyBtn();
  const runTest = () => {
    if (location.hash === "#test-remind") gcTestRemind();
    else if (location.hash === "#test-call") gcTestCall();
    else if (location.hash === "#test-notify") gcTestNotify();
    else if (location.hash === "#test-platcheck") gcTestPlatCheck();
    else if (location.hash === "#test-all") gcTestAll();
  };
  if (["#test-remind", "#test-call", "#test-notify", "#test-platcheck", "#test-all"].includes(location.hash)) runTest();
  else gcCheck();
  setInterval(gcCheck, 60 * 1000);
  window.addEventListener("hashchange", runTest);

  // 打電話提醒:開網站先讀一次退貨,之後每小時再讀(過了半夜也會換成新的一天)
  if (location.hash !== "#test-call" && typeof loadReturnsQuietly === "function") {
    loadReturnsQuietly();
    setInterval(loadReturnsQuietly, 60 * 60 * 1000);
  }
}
